"use strict";
// MCP 注册：VS Code 的 MCP server definition provider（特性检测）、供外部客户端使用的稳定启动器，
// 以及按客户端生成的配置片段。扩展从不代写任何客户端的配置文件。
const fs = require("fs/promises");
const path = require("path");
const { execFile } = require("child_process");

const PROVIDER_ID = "emberprobe";
const MIN_NODE_MAJOR = 18;
const CLIENTS = Object.freeze(["claude", "codex", "json"]);

// 启动器路径稳定（globalStorage/mcp），内容随每次激活重写为当前扩展安装路径。
function launcherSource(serverPath) {
    return [
        "// Generated by EmberProbe on activation; points at the installed extension's MCP server.",
        '"use strict";',
        `require(${JSON.stringify(serverPath)})`,
        "    .main()",
        "    .catch((error) => {",
        "        process.stderr.write(`EmberProbe MCP server failed: ${(error && error.stack) || error}\\n`);",
        "        process.exit(1);",
        "    });",
        ""
    ].join("\n");
}

function tomlString(value) {
    return JSON.stringify(String(value));
}

// 命令行片段：Windows 路径不会含双引号；POSIX 用单引号避免 $、` 等被 shell 展开。
function shellQuote(value, platform = process.platform) {
    return platform === "win32" ? `"${value}"` : `'${String(value).replace(/'/g, "'\\''")}'`;
}

/**
 * 生成客户端配置片段。toolsets 为空（默认工具集）时不写环境变量。
 * @param {"claude" | "codex" | "json"} client
 */
function configSnippet(client, launcher, toolsets, platform = process.platform) {
    const env = toolsets ? { EMBERPROBE_MCP_TOOLSETS: toolsets } : null;
    if (client === "claude") {
        const envFlag = env ? ` -e EMBERPROBE_MCP_TOOLSETS=${toolsets}` : "";
        return `claude mcp add --scope user${envFlag} emberprobe -- node ${shellQuote(launcher, platform)}`;
    }
    if (client === "codex") {
        const lines = ["[mcp_servers.emberprobe]", 'command = "node"', `args = [${tomlString(launcher)}]`];
        if (env) lines.push(`env = { EMBERPROBE_MCP_TOOLSETS = ${tomlString(toolsets)} }`);
        return lines.join("\n");
    }
    return JSON.stringify(
        { mcpServers: { emberprobe: { command: "node", args: [launcher], ...(env ? { env } : {}) } } },
        null,
        2
    );
}

function nodeVersion(run = execFile) {
    return new Promise((resolve) => {
        run("node", ["--version"], { timeout: 5000, windowsHide: true }, (error, stdout) => {
            if (error) return resolve({ found: false, version: "", error: String(error.code || error.message) });
            const version = String(stdout || "").trim();
            const major = Number(/^v?(\d+)/.exec(version)?.[1] || 0);
            resolve({ found: true, version, supported: major >= MIN_NODE_MAJOR });
        });
    });
}

class McpRegistration {
    /**
     * @param {{
     *   vscode: any, context: any, t: (key: string, params?: Record<string, any>) => string,
     *   isAvailable: () => boolean, instanceId: () => string, toolsets: () => string,
     *   onResolve: () => Promise<void>, onConfigured?: () => void, nodeVersion?: typeof nodeVersion
     * }} options
     */
    constructor(options) {
        this.vscode = options.vscode;
        this.context = options.context;
        this.t = options.t;
        this.isAvailable = options.isAvailable;
        this.instanceId = options.instanceId;
        this.toolsets = options.toolsets;
        this.onResolve = options.onResolve;
        this.onConfigured = options.onConfigured || (() => {});
        this.nodeVersion = options.nodeVersion || nodeVersion;
        this.emitter = null;
        this.registered = false;
    }

    serverPath() {
        return path.join(this.context.extensionPath, "dist", "mcp-server.js");
    }

    launcherPath() {
        return path.join(this.context.globalStorageUri.fsPath, "mcp", "emberprobe-mcp.js");
    }

    async writeLauncher() {
        const file = this.launcherPath();
        await fs.mkdir(path.dirname(file), { recursive: true });
        await fs.writeFile(file, launcherSource(this.serverPath()));
        return file;
    }

    // 旧版 VS Code 没有 MCP API 时安静跳过；返回是否已注册。
    register() {
        const lm = this.vscode.lm;
        if (typeof lm?.registerMcpServerDefinitionProvider !== "function" || !this.vscode.McpStdioServerDefinition)
            return false;
        this.emitter = new this.vscode.EventEmitter();
        const provider = {
            onDidChangeMcpServerDefinitions: this.emitter.event,
            provideMcpServerDefinitions: () => this.definitions(),
            resolveMcpServerDefinition: async (definition) => {
                // VS Code 在用户同意 MCP 信任提示后才解析定义；此时为本窗口启动 Bridge。
                if (!this.isAvailable()) return undefined;
                await this.onResolve();
                return definition;
            }
        };
        this.context.subscriptions.push(lm.registerMcpServerDefinitionProvider(PROVIDER_ID, provider), this.emitter);
        this.registered = true;
        return true;
    }

    definitions() {
        if (!this.isAvailable()) return [];
        const env = { ELECTRON_RUN_AS_NODE: "1", EMBERPROBE_BRIDGE_INSTANCE: this.instanceId() };
        const toolsets = this.toolsets();
        if (toolsets) env.EMBERPROBE_MCP_TOOLSETS = toolsets;
        const version = this.context.extension?.packageJSON?.version;
        return [
            new this.vscode.McpStdioServerDefinition("EmberProbe", process.execPath, [this.serverPath()], env, version)
        ];
    }

    changed() {
        this.emitter?.fire();
    }

    async copyConfig() {
        const picks = CLIENTS.map((client) => ({ label: this.t(`mcp.client.${client}`), client }));
        const choice = await this.vscode.window.showQuickPick(picks, { placeHolder: this.t("mcp.pickClient") });
        if (!choice) return null;
        const launcher = await this.writeLauncher();
        const snippet = configSnippet(choice.client, launcher, this.toolsets());
        await this.vscode.env.clipboard.writeText(snippet);
        this.onConfigured();
        const node = await this.nodeVersion();
        if (!node.found) this.vscode.window.showWarningMessage(this.t("mcp.nodeMissing", { minimum: MIN_NODE_MAJOR }));
        else if (!node.supported)
            this.vscode.window.showWarningMessage(
                this.t("mcp.nodeTooOld", { version: node.version, minimum: MIN_NODE_MAJOR })
            );
        else this.vscode.window.showInformationMessage(this.t("mcp.configCopied", { client: choice.label }));
        return { client: choice.client, snippet, node };
    }
}

module.exports = { McpRegistration, configSnippet, launcherSource, nodeVersion, PROVIDER_ID, CLIENTS, MIN_NODE_MAJOR };
